using System;
using System.Linq;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;
namespace TasiaCraft { public partial class Editor {
 HashSet<string> selectedClipIds=new HashSet<string>(); string openedGroupId;
 List<Clip> SelectedClips(){
  if(openedGroupId!=null&&!project.Groups.Any(g=>g.Id==openedGroupId))openedGroupId=null;
  if(selected==null){selectedClipIds.Clear();return new List<Clip>();}
  if(!project.Clips.Contains(selected)){selected=null;selectedClipIds.Clear();return new List<Clip>();}
  if(!selectedClipIds.Contains(selected.Id)){selectedClipIds.Clear();foreach(var c in ClipGroups.Expand(project,new[]{selected},openedGroupId))selectedClipIds.Add(c.Id);}
  return project.Clips.Where(c=>selectedClipIds.Contains(c.Id)).ToList();
 }
 void SetSelected(IEnumerable<Clip> clips){var list=clips.ToList();selectedClipIds=new HashSet<string>(list.Select(c=>c.Id));selected=list.FirstOrDefault();}
 void SyncSelection(){if(live!=null)live.SetSelections(SelectedClips());}
 void SelectClip(Clip c,bool toggle,bool preserve){var current=SelectedClips();if(c==null)SetSelected(new Clip[0]);else{var unit=ClipGroups.Expand(project,new[]{c},openedGroupId);if(toggle){bool remove=unit.All(x=>current.Contains(x));foreach(var x in unit){if(remove)current.Remove(x);else if(!current.Contains(x))current.Add(x);}SetSelected(current);}else if(!preserve||!current.Contains(c))SetSelected(unit);}SyncSelection();Props();}
 void SelectAllClips(){SetSelected(openedGroupId==null?project.Clips:project.Clips.Where(c=>project.Groups.First(g=>g.Id==openedGroupId).ClipIds.Contains(c.Id)));SyncSelection();Props();DrawTimeline();}
 void GroupSelection(){if(busy)return;var clips=SelectedClips();if(clips.Count<2||clips.Any(TrackLocked)||clips.Any(c=>ClipGroups.ForClip(project,c)!=null)){Info("Select at least two ungrouped clips on unlocked tracks.");return;}Checkpoint();int n=1;while(project.Groups.Any(g=>g.Name=="Group"+n))n++;ClipGroups.Create(project,clips,"Group"+n);Refresh();}
 void UngroupSelection(){if(busy)return;var clips=SelectedClips();if(openedGroupId!=null){Info("Return to Main Timeline to ungroup.");return;}var units=ClipGroups.Expand(project,clips);if(units.Any(TrackLocked)){Info("Track is locked.");return;}if(!units.Any(c=>ClipGroups.ForClip(project,c)!=null))return;Checkpoint();ClipGroups.Ungroup(project,units);SetSelected(units);Refresh();}
 void OpenSelectedGroup(){var clips=SelectedClips();if(clips.Count==0)return;var g=ClipGroups.ForClip(project,clips[0]);if(g==null||clips.Any(c=>!g.ClipIds.Contains(c.Id)))return;openedGroupId=g.Id;SetSelected(new Clip[0]);Refresh();}
 void CloseGroup(){openedGroupId=null;SetSelected(new Clip[0]);Refresh();}
 void DeleteSelection(){if(busy)return;var clips=SelectedClips();if(clips.Count==0)return;if(clips.Any(TrackLocked)){Info("Track is locked.");return;}Checkpoint();project.Clips.RemoveAll(c=>clips.Contains(c));ClipGroups.Prune(project);SetSelected(new Clip[0]);Refresh();}
 void MoveSelectionTimeline(double seconds,int tracks){if(busy)return;try{var clips=SelectedClips();if(clips.Count==0)return;var result=new ClipMoveOperation(project,clips).EvaluateTimeline(seconds,tracks);if(!result.Changes)return;Checkpoint();result.Apply();Refresh();}catch(Exception e){Info(e.Message);}}
 bool MultiProps(){var clips=SelectedClips();if(clips.Count<2)return false;properties.Children.Add(Text(clips.Count+" clips selected",14));var g=ClipGroups.ForClip(project,clips[0]);if(g!=null&&clips.All(c=>g.ClipIds.Contains(c.Id))){properties.Children.Add(Text(g.Name));properties.Children.Add(Btn("Rename Group",RenameSelectedGroup));properties.Children.Add(Btn("Open Group",OpenSelectedGroup));properties.Children.Add(Btn("Ungroup  Ctrl+U",UngroupSelection));}else properties.Children.Add(Btn("Group  Ctrl+G",GroupSelection));properties.Children.Add(Text("Drag to move the selection together. Ctrl/Shift-click toggles clips. Open a group to edit its members.",12,muted));return true;}
 void WireSelectionClip(Border b,Clip c){Point origin=new Point();ClipMoveOperation operation=null;bool changed=false;double start=0,oldIn=0,oldDuration=0;int track=0,trim=0;
  b.MouseLeftButtonDown+=(s,e)=>{if(busy)return;Keyboard.Focus(this);bool toggle=(Keyboard.Modifiers&(ModifierKeys.Control|ModifierKeys.Shift))!=0;SelectClip(c,toggle,true);e.Handled=true;if(toggle){DrawTimeline();return;}var clips=SelectedClips();try{operation=new ClipMoveOperation(project,clips);}catch(Exception ex){Info(ex.Message);DrawTimeline();return;}origin=e.GetPosition(timeline);trim=clips.Count==1?(e.GetPosition(b).X<7?1:e.GetPosition(b).X>b.Width-7?2:0):0;oldIn=c.In;oldDuration=c.Duration;start=clips.Min(x=>x.Start);track=clips.Min(x=>x.Track);changed=false;b.CaptureMouse();};
  b.MouseMove+=(s,e)=>{b.Cursor=Cursors.SizeAll;if(operation==null||!b.IsMouseCaptured)return;var point=e.GetPosition(timeline);double delta=(point.X-origin.X)/zoom;if(!changed&&Math.Abs(point.X-origin.X)+Math.Abs(point.Y-origin.Y)<2)return;var clips=SelectedClips();if(trim!=0){if(TrackLocked(c))return;var media=project.Media.FirstOrDefault(m=>m.Id==c.MediaId);double maximum=media==null||media.Kind=="image"?86400:media.Duration;if(trim==1){delta=Math.Max(-Math.Min(start,oldIn/c.Speed),Math.Min(oldDuration-.1,delta));if(c.Start==start+delta)return;}else{delta=Math.Max(.1,Math.Min((maximum-oldIn)/c.Speed,oldDuration+delta));if(c.Duration==delta)return;}if(!changed){Checkpoint();changed=true;}if(trim==1){c.Start=start+delta;c.In=oldIn+delta*c.Speed;c.Duration=oldDuration-delta;}else c.Duration=delta;c.FadeIn=Math.Min(c.FadeIn,c.Duration);c.FadeOut=Math.Min(c.FadeOut,c.Duration);Canvas.SetLeft(b,110+c.Start*zoom);b.Width=Math.Max(8,c.Duration*zoom);live.Refresh();return;}if((Keyboard.Modifiers&ModifierKeys.Shift)==0&&!clips.Any(x=>project.SnapDisabledTracks.Contains(x.Track))){foreach(var t in project.Clips.Where(x=>!clips.Contains(x)&&!project.SnapDisabledTracks.Contains(x.Track)).SelectMany(x=>new[]{x.Start,x.Start+x.Duration}).Concat(new[]{head,0.0})){if(Math.Abs(start+delta-t)*zoom<8){delta=t-start;break;}}}try{var result=operation.EvaluateTimeline(delta,-(int)Math.Round((point.Y-origin.Y)/64));if(result.Changes){if(!changed){Checkpoint();changed=true;}result.Apply();Canvas.SetLeft(b,110+(start+result.Seconds)*zoom);Canvas.SetTop(b,38+(project.TrackCount-1-track-result.Tracks)*64);live.Refresh();}}catch(Exception ex){Info(ex.Message);}e.Handled=true;};
  b.MouseLeftButtonUp+=(s,e)=>{if(operation==null)return;operation=null;b.ReleaseMouseCapture();DrawTimeline();Props();live.Refresh();UpdateClock();e.Handled=true;};
  var menu=new ContextMenu();Action<string,string,Action> add=(name,gesture,action)=>{var item=new MenuItem{Header=name,InputGestureText=gesture};item.Click+=(s,e)=>action();menu.Items.Add(item);};add("Cut","Ctrl+X",Cut);add("Copy","Ctrl+C",Copy);add("Paste","Ctrl+V",Paste);add("Delete","Del",DeleteSelection);menu.Items.Add(new Separator());add("Group","Ctrl+G",GroupSelection);add("Ungroup","Ctrl+U",UngroupSelection);add("Open group","",OpenSelectedGroup);add("Rename Group","",RenameSelectedGroup);add("Main Timeline","",CloseGroup);b.ContextMenu=menu;b.ContextMenuOpening+=(s,e)=>{SelectClip(c,false,true);SyncSelection();};
 }
} }
